    # the row with the longest uninterrupted foreground run.
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        a = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        b = r

        def best_run(row):
            best = (0, -1)
            c = 0
            while c < w:
                if row[c] == bg:
                    c += 1
                    continue
                start = c
                color = row[c]
                while c < w and row[c] == color:
                    c += 1
                if c - start > best[0]:
                    best = (c - start, c - 1)
            return best

        target = max(range(a, b), key=lambda rr: best_run(grid[rr])[0])
        length, end = best_run(grid[target])
        if length:
            for c in range(end + 1, w):
                out[target][c] = 1
    return out
